#!/usr/bin/env node
// Copies the Pyodide runtime files this app actually needs at runtime from
// node_modules/pyodide into public/pyodide/, where the Python worker loads
// them from (see public/pyodide-worker.js). Runs automatically via the
// "postinstall" script in package.json, so `public/pyodide/` never needs to
// be committed to git — it's regenerated by `npm install`, and always
// matches whatever `pyodide` version package.json currently pins.
//
// Why not let a bundler handle this: Turbopack has no first-party recipe
// for Pyodide's WASM + data-file assets, and bundling the worker itself
// causes a real, confirmed incompatibility (see the AlgoForge project's
// python-course-plan.md). Serving these as plain static files sidesteps
// both problems.

import { copyFileSync, existsSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(__dirname, "..");
const srcDir = join(repoRoot, "node_modules", "pyodide");
const destDir = join(repoRoot, "public", "pyodide");

// Only the files actually fetched at runtime by loadPyodide()/pyodide.mjs —
// not pyodide.d.ts / ffi.d.ts (type declarations, irrelevant here; our TS
// code gets Pyodide's types straight from node_modules) and not the
// console.html demo pages Pyodide ships.
const FILES = ["pyodide.mjs", "pyodide.asm.mjs", "pyodide.asm.wasm", "python_stdlib.zip", "pyodide-lock.json"];

if (!existsSync(srcDir)) {
  console.warn(`[copy-pyodide-assets] node_modules/pyodide not found — skipping (is "pyodide" installed?).`);
  process.exit(0);
}

mkdirSync(destDir, { recursive: true });

let copied = 0;
for (const file of FILES) {
  const from = join(srcDir, file);
  const to = join(destDir, file);
  if (!existsSync(from)) {
    console.warn(`[copy-pyodide-assets] expected file missing, skipped: ${file}`);
    continue;
  }
  copyFileSync(from, to);
  copied++;
}

console.log(`[copy-pyodide-assets] copied ${copied}/${FILES.length} files to public/pyodide/`);
